<?php $this->layout('layouts/admin', ['title' => 'Khách hàng', 'pageTitle' => 'Quản lý khách hàng', 'activeMenu' => 'customer']) ?>
<?php $this->start('page') ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="h4 fw-bold mb-1">Danh sách khách hàng</h2><p class="text-secondary mb-0"><?= count($customers) ?> tài khoản khách hàng</p></div></div>
<div class="card border-0 shadow-sm rounded-4"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Mã</th><th>Khách hàng</th><th>Điện thoại</th><th>Địa chỉ</th><th>Đơn đặt</th><th>Chi tiêu</th><th class="text-end">Thao tác</th></tr></thead><tbody><?php foreach ($customers as $customer) : ?><tr><td>#<?= (int)$customer['userId'] ?></td><td><strong><?= $this->e($customer['name']) ?></strong><small class="d-block text-secondary"><?= $this->e($customer['email']) ?></small></td><td><?= $this->e($customer['phoneNumber'] ?: '—') ?></td><td><?= $this->e($customer['address'] ?: '—') ?></td><td><?= (int)($customer['bookingCount'] ?? 0) ?></td><td><?= number_format((float)($customer['totalSpent'] ?? 0), 0, ',', '.') ?>₫</td><td><div class="d-flex justify-content-end gap-1"><a href="/admin/customers/show/<?= (int)$customer['userId'] ?>" class="btn btn-sm btn-outline-primary" title="Xem"><i class="bi bi-eye"></i></a><a href="/admin/customers/edit/<?= (int)$customer['userId'] ?>" class="btn btn-sm btn-outline-dark" title="Sửa"><i class="bi bi-pencil"></i></a><form action="/admin/customers/delete/<?= (int)$customer['userId'] ?>" method="POST" onsubmit="return confirm('Xóa tài khoản và toàn bộ dữ liệu liên quan?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger" title="Xóa"><i class="bi bi-trash"></i></button></form></div></td></tr><?php endforeach; ?><?php if (!$customers) : ?><tr><td colspan="7" class="text-center text-secondary py-5">Chưa có khách hàng.</td></tr><?php endif; ?></tbody></table></div></div>
<?php $this->stop() ?>
